-module(clause_unicode).
-export([table/1, class/1, cases/1, flags/1, compose_pair/2]).

% Clause's Unicode table queries (plan step 41O1, docs/builtins.md#unicode-util): runtime builtins over the tables
% generated by tools/unicode/generate.py, which replace these bodies at registration. unicode_util answers OTP's
% functions over them; the argument is always a code point it has checked.

% {CCC, Canon, Compat, Category} of a code point, as OTP's unicode_table/1 with the category resolved.
table(_) -> erlang:error(undef).

% The canonical combining class.
class(_) -> erlang:error(undef).

% {Upper, Lower, Title, Fold}.
cases(_) -> erlang:error(undef).

% The property bits of unicode_util.erl.
flags(_) -> erlang:error(undef).

% The canonical composition of a pair, or false.
compose_pair(_, _) -> erlang:error(undef).
